reference_solution:
n = int(input())
if n % 2 == 0:
    print("Bench: Left")
else:
    print("Bench: Right")

amount = int(input())
if amount > 0:
    print("Category: CREDIT")
elif amount < 0:
    print("Category: DEBIT")
else:
    print("Category: ZERO")

x, y = map(int, input().split())
if x == 0 and y == 0:
    loc = "ORIGIN"
elif x == 0 or y == 0:
    loc = "AXIS"
elif x > 0 and y > 0:
    loc = "I"
elif x < 0 and y > 0:
    loc = "II"
elif x < 0 and y < 0:
    loc = "III"
else:
    loc = "IV"
print(f"Location: {loc}")

a, b, c = map(int, input().split())
if a <= b and a <= c:
    vendor, price = "A", a
elif b <= c:
    vendor, price = "B", b
else:
    vendor, price = "C", c
print(f"Vendor: {vendor}")
print(f"Price: {price}")

a, b, c = map(int, input().split())
if a + b <= c or a + c <= b or b + c <= a:
    kind = "INVALID"
elif a == b == c:
    kind = "EQUILATERAL"
elif a == b or b == c or a == c:
    kind = "ISOSCELES"
else:
    kind = "SCALENE"
print(f"Triangle: {kind}")

d, m, y = map(int, input().split())
leap = (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
if m < 1 or m > 12:
    valid = False
else:
    if m == 2:
        max_day = 29 if leap else 28
    elif m in (4, 6, 9, 11):
        max_day = 30
    else:
        max_day = 31
    valid = 1 <= d <= max_day
print("Date: VALID" if valid else "Date: INVALID")

units = int(input())
if units <= 100:
    bill = units * 2.0
elif units <= 300:
    bill = 100 * 2.0 + (units - 100) * 3.5
else:
    bill = 100 * 2.0 + 200 * 3.5 + (units - 300) * 5.0
print(f"Bill: {bill:.2f}")

ch = input()
if 'A' <= ch <= 'Z':
    cls = "UPPERCASE"
elif 'a' <= ch <= 'z':
    cls = "LOWERCASE"
elif '0' <= ch <= '9':
    cls = "DIGIT"
else:
    cls = "SPECIAL"
print(f"Class: {cls}")

a, b = input().split()
if a == b:
    result = "Draw"
elif a == "rock":
    if b == "scissors" or b == "lizard":
        result = "Player 1 wins"
    else:
        result = "Player 2 wins"
elif a == "paper":
    if b == "rock" or b == "spock":
        result = "Player 1 wins"
    else:
        result = "Player 2 wins"
elif a == "scissors":
    if b == "paper" or b == "lizard":
        result = "Player 1 wins"
    else:
        result = "Player 2 wins"
elif a == "lizard":
    if b == "spock" or b == "paper":
        result = "Player 1 wins"
    else:
        result = "Player 2 wins"
else:
    if b == "scissors" or b == "rock":
        result = "Player 1 wins"
    else:
        result = "Player 2 wins"
print(f"Result: {result}")

score, income, debt = map(int, input().split())
fails = []
if score < 700:
    fails.append("credit score")
if income < 30000:
    fails.append("income")
if debt > 40:
    fails.append("debt ratio")
if not fails:
    print("Decision: APPROVED")
else:
    print("Decision: REJECTED")
    for f in fails:
        print(f"Failed: {f}")

vehicle, day, minutes = input().split()
minutes = int(minutes)
hours = (minutes + 59) // 60
if vehicle == "CAR":
    cap = 250
    if day == "WEEKDAY":
        r1, r2, r3 = 20, 15, 10
    else:
        r1, r2, r3 = 30, 20, 15
elif vehicle == "BIKE":
    cap = 80
    if day == "WEEKDAY":
        r1, r2, r3 = 5, 4, 3
    else:
        r1, r2, r3 = 8, 6, 4
else:
    cap = 600
    if day == "WEEKDAY":
        r1, r2, r3 = 50, 40, 30
    else:
        r1, r2, r3 = 70, 55, 40
if hours <= 2:
    fee = hours * r1
elif hours <= 5:
    fee = 2 * r1 + (hours - 2) * r2
else:
    fee = 2 * r1 + 3 * r2 + (hours - 5) * r3
if fee > cap:
    fee = cap
print(f"Billable hours: {hours}")
print(f"Parking fee: {fee}")

pin, w = input().split()
w = int(w)
if len(pin) != 6 or pin[0] == "0":
    print("Error: INVALID PINCODE")
elif w < 1 or w > 25000:
    print("Error: INVALID WEIGHT")
else:
    prefix = int(pin[:2])
    if prefix == 50:
        zone = "LOCAL"
    elif 51 <= prefix <= 69:
        zone = "REGIONAL"
    else:
        zone = "NATIONAL"
    if w <= 500:
        slab = 0
    elif w <= 2000:
        slab = 1
    elif w <= 5000:
        slab = 2
    else:
        slab = 3
    if zone == "LOCAL":
        charge = [40, 70, 120, 200][slab]
    elif zone == "REGIONAL":
        charge = [60, 110, 190, 320][slab]
    else:
        charge = [90, 160, 280, 450][slab]
    print(f"Zone: {zone}")
    print(f"Charge: {charge}")

age, income, emp, score = input().split()
age = int(age)
income = int(income)
score = int(score)
if age < 21 or age > 65 or score < 600:
    decision = "DECLINED"
elif emp == "SALARIED":
    if income >= 100000 and score >= 750:
        decision = "PLATINUM"
    elif income >= 50000 and score >= 700:
        decision = "GOLD"
    elif income >= 25000:
        decision = "SILVER"
    else:
        decision = "DECLINED"
elif emp == "SELF_EMPLOYED":
    if income >= 150000 and score >= 780:
        decision = "PLATINUM"
    elif income >= 80000 and score >= 720:
        decision = "GOLD"
    elif income >= 40000 and score >= 650:
        decision = "SILVER"
    else:
        decision = "DECLINED"
else:
    if income >= 20000 and score >= 700:
        decision = "SILVER"
    else:
        decision = "DECLINED"
print(f"Decision: {decision}")
